const wordsSay = t3("Här är de nya orden. Tryck på ett ord för att se vad det betyder och ett exempel.", "Here are the new words. Tap a word to see what it means and an example.", "هذه هي الكلمات الجديدة. اضغط على كلمة لترى معناها ومثالًا عليها.");
/* a choice question with exactly three distinct options */
const choice = (right: string, wrong: string[], q: Draw[], sol: Draw[], h: {say: T3; draw: Draw[]}): Problem | null => {
  const opts = shuffle([right, ...wrong.filter(w => w !== right)].filter((v, i, a) => a.indexOf(v) === i)).slice(0, 3);
  if (opts.length < 3 || !opts.includes(right)) return null;
  return {kind: "choice", opts, ans: opts.indexOf(right), show: right, q, sol, hint: h};
};

