word("marsvin", {sv: "marsvin (ett)", m: "marsvin(et|en|ets)?", d: t3("Ett litet, runt husdjur utan svans. Det piper och äter grönsaker.", "A small, round pet with no tail. It squeaks and eats vegetables.", "حيوان أليف صغير ومستدير بلا ذيل، يُصدر صفيرًا ويأكل الخضار."), ex: "Klassens marsvin heter Kanel och Muffin.", tr: {en: "guinea pig", ar: "خنزير غينيا"}, wrong: ["kanin", "hamster"], gap: ["Klassen fick två små", "marsvin", "som bodde i en bur."], gapForm: "marsvin", form: "ett marsvin – två marsvin"});
