word("stro", {sv: "strö (ett)", m: "strö(et)?", d: t3("Det mjuka man lägger på golvet i en bur, till exempel sågspån.", "The soft stuff you put on the floor of a cage, for example wood shavings.", "المادة الطرية التي توضع في أرض القفص، مثل نشارة الخشب."), ex: "Vi byter strö i buren varje vecka.", tr: {en: "bedding (for animals)", ar: "فَرْشة الحيوانات"}, wrong: ["sand", "snö"], gap: ["Vi bytte", "strö", "i buren på onsdagen."], gapForm: "strö", form: "ett strö – ströet"});
word("skota", {sv: "sköta", m: "sköt(a|er|te|t)", d: t3("Ta hand om någon eller något, så att det mår bra.", "Take care of someone or something, so that it is well.", "أن تعتني بشخص أو بشيء حتى يكون بخير."), ex: "Yasmin sköter marsvinen i dag.", tr: {en: "look after, take care of", ar: "يعتني بـ"}, syn: ["ta hand om"], opp: ["strunta i"], wrong: ["glömma", "sälja"], gap: ["Vem ska", "sköta", "marsvinen på fredag?"], gapForm: "sköta", form: "sköta – skötte – har skött"});
word("gnaga", {sv: "gnaga", m: "gnag(a|ar|de|t)", d: t3("Bita lite i taget med framtänderna, länge.", "Bite a little at a time with the front teeth, for a long time.", "أن يقضم قليلًا قليلًا بأسنانه الأمامية مدة طويلة."), ex: "Marsvinet gnagde på en morot.", tr: {en: "gnaw, nibble", ar: "يقضم"}, syn: ["knapra"], wrong: ["simma", "skälla"], gap: ["Kanel satt och", "gnagde", "på en morot."], gapForm: "gnagde", form: "gnaga – gnagde – har gnagt"});
word("morot", {sv: "morot (en)", m: "mor(ot|oten|ötter|ötterna)", d: t3("En lång, orange grönsak som växer i jorden.", "A long, orange vegetable that grows in the ground.", "خضار طويلة برتقالية تنمو في التراب."), ex: "Marsvin tycker om morötter.", tr: {en: "carrot", ar: "جزرة"}, wrong: ["potatis", "äpple"], gap: ["Leo skar en", "morot", "i små bitar."], gapForm: "morot", form: "en morot – morötter"});
word("turas", {sv: "turas om", m: "tur(as|ades|ats) om", d: t3("Göra något en i taget: först du, sedan jag.", "Do something one at a time: first you, then me.", "أن يقوم كلٌّ بالعمل في دوره: أنت أولًا ثم أنا."), ex: "Vi turas om att mata marsvinen.", tr: {en: "take turns", ar: "يتناوبون"}, syn: ["byta av varandra"], wrong: ["bråka", "gömma sig"], gap: ["Ni får", "turas om", "att sköta marsvinen."], gapForm: "turas om", form: "turas om – turades om – har turats om"});
